import java.io.*;
import java.util.*;

public class F {
// checks: 1. edge cases   2. overflow   3. possible errors (e.g 1/0, arr[out])   4. time/space complexity
    int n;
    int m;
    int[] arr;
    int required;
    HashMap<Integer, TreeSet<Integer>> typeDays;
    void solver() throws IOException {
        n = in.intNext(); m = in.intNext();
        arr = in.nextIntArray(n);
        required = sum(arr);
        typeDays = new HashMap<>();
        for (int i = 0; i < m; i++) {
            int d = in.intNext(), typ = in.intNext();
            if (arr[typ - 1] <= 0) continue;
            if (!typeDays.containsKey(typ)) typeDays.put(typ, new TreeSet<>());
            typeDays.get(typ).add(d);
        }

        int lo = required;
        int hi = 2 * required;
        int valid = hi;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (isEnough(mid)) {
                valid = mid;
                hi = mid - 1;
            } else
                lo = mid + 1;
        }
        out.println(valid);
    }

    boolean isEnough(int day) {
        int totalCoin = day;
        int req = required;

        int[] ddays = new int[day + 1];
        for (int typ : typeDays.keySet()) {
            Integer lastDay = typeDays.get(typ).floor(day);
            if (lastDay == null) continue;
            ddays[lastDay] += arr[typ - 1];
        }
//        out.println(ddays);
        int removed = 0;
        for (int i = 1; i < day + 1; i++) {
            int coins = i - removed;
            int toRemove = min(coins, ddays[i]);
            removed += toRemove;
            totalCoin -= toRemove;
            req -= toRemove;
        }
//        out.pp(req, totalCoin);
        return req * 2 <= totalCoin;
    }


